loginUrl:
function login() {
    var info = source.getLoginInfoMap();
    if (!info) throw new Error('请先输入邮箱和密码');
    var email = info.get('登录邮箱');
    var pwd = info.get('登录密码');
    email = email == null ? '' : String(email).trim();
    pwd = pwd == null ? '' : String(pwd);
    if (!email || !pwd) throw new Error('请先输入邮箱和密码');
    var url = 'https://www.cunshu.la/login.php';
    var body = 'email=' + encodeURIComponent(email) + '&password=' + encodeURIComponent(pwd);
    var headers = {'Content-Type': 'application/x-www-form-urlencoded'};
    var resp = java.post(url, body, headers, 30000);
    if (!resp) throw new Error('登录请求失败');
    var respBody = resp.body();
    if (!respBody) throw new Error('登录响应为空');
    if (respBody.indexOf('邮箱或密码错误') >= 0) throw new Error('邮箱或密码错误');
    if (respBody.indexOf('auth-form') >= 0) throw new Error('登录失败，请重试');
}

ruleBookInfo.author:
@js:
var text = result || "";
var title = "";
try { title = baseElement.select(".ph-name").text(); } catch(e) {}
text = title + "\n" + text;
var m = text.match(/作者\s*[：:]\s*([^\n\r，。；、！？!?*（）()【】\[\]{}《》<>"'\s]{1,16})/);
if (m) {
  var name = m[1].replace(/[，。；、！？!?*（）()【】\[\]{}《》<>"'\s]+$/, "");
  name = name.split(/简介|又名|本书|作品|作者|连载|更新|小说|全文/)[0];
  if (name) { result = name; }
  else { result = ""; }
} else {
  var m2 = text.match(/\b[bB][yY]\s*[：:]?\s*([^\n\r，。；、！？!?*（）()【】\[\]{}《》<>"'\s]{1,16})/);
  if (m2) {
    var name2 = m2[1].replace(/[，。；、！？!?*（）()【】\[\]{}《》<>"'\s]+$/, "");
    name2 = name2.split(/简介|又名|本书|作品|作者|连载|更新|小说|全文/)[0];
    if (name2) { result = name2; }
    else { result = ""; }
  } else { result = ""; }
}

ruleContent.content:
.chapter-text@html@js:
var html = result;
html = html.replace(/<span class="kw-protect">([\s\S]*?)<\/span>/g, function(m, inner) {
    return inner.replace(/<i class="cr" data-cp="([0-9a-fA-F]+)"><\/i>/g, function(m2, cp) {
        var code = parseInt(cp, 16);
        if (code && !isNaN(code)) return String.fromCodePoint(code);
        return '';
    });
});
html = html.replace(/<br\s*\/?>/gi, '\n');
html = html.replace(/<[^>]+>/g, '');
html = html.replace(/\n{3,}/g, '\n\n');
result = html;

